<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { useRouter } from 'vue-router'
import MarketNavigation from '@/components/market/MarketNavigation.vue'
import { saveMarketHomeTab, type MarketHomeTab } from '@/utils/marketHomeTab'
const router=useRouter()
type Row=Record<string, any>
const runs=ref<Row[]>([]),run=ref(''),overview=ref<Row|null>(null),detail=ref<Row|null>(null),history=ref<Row[]>([])
const index=ref(0),offset=ref(0),error=ref(''),loading=ref(false)
let generation=0
onBeforeUnmount(()=>{generation++})
const base='/api/v1/research/subing-decision/runs'
async function get(url:string){const r=await fetch(url);if(!r.ok)throw new Error('回放结果不可用或校验失败，请检查已登记研究结果。');return r.json()}
async function select(){const g=++generation;loading.value=true;error.value='';detail.value=null;overview.value=null;history.value=[];try{const o=await get(`${base}/${run.value}`);if(g!==generation)return;overview.value=o;index.value=o.times.length-1;offset.value=0;await seek()}catch(e){if(g===generation)error.value=String((e as Error).message)}finally{if(g===generation)loading.value=false}}
async function seek(){const g=++generation;loading.value=true;error.value='';detail.value=null;history.value=[];try{const [d,h]=await Promise.all([get(`${base}/${run.value}/decision?index=${index.value}`),get(`${base}/${run.value}/history?index=${index.value}&offset=${offset.value}`)]);if(g!==generation)return;detail.value=d;history.value=h.items}catch(e){if(g===generation)error.value=String((e as Error).message)}finally{if(g===generation)loading.value=false}}
function move(n:number){index.value=Math.max(0,Math.min((overview.value?.times.length??1)-1,index.value+n));offset.value=0;void seek()}
function home(tab:MarketHomeTab){saveMarketHomeTab(tab);void router.push('/market')}
async function loadRuns(){try{runs.value=(await get(base)).runs;run.value=runs.value[0]?.id??'';if(run.value)await select();else error.value='暂无已登记的完整焦煤回放。'}catch(e){error.value=(e as Error).message}}
onMounted(loadRuns)
const d=computed(()=>detail.value?.decision)
const labels:Record<string,string>={BAR_CLOSE:'普通完成Bar',DAY_END:'日终记录',NEXT_OPEN_AFTER_DAY_END:'下一开盘检查',NEXT_SESSION_OPEN_REVIEW:'记录持仓，等待下一开盘复核',EXIT_EXECUTION:'既有退出义务继续，等待后续模型成交',INTENT_EXECUTION:'等待后续模型执行',BREAK_CONFIRMATION:'等待连续三根收盘确认',REQUIRED_FACTS:'等待必要事实恢复',FRESH_POSITION:'等待新的合格位置',NEW_VALID_ENTRY:'等待新的有效入场机会',PROFIT_1R_TIER1_CLEAR:'首次1R目标触发清仓',PROFIT_1R_REDUCE:'首次1R目标触发减仓',FIXED_STOP:'固定初始止损',EMA_CLEAR:'EMA技术退出',ADD_PROTECTION:'加仓层价格保护',ORDINARY_REDUCTION:'技术减仓',ENVIRONMENT_FACTS_MISSING:'环境事实不足',TECHNICAL_FACTS_UNKNOWN:'技术事实不足',RECONCILIATION_REQUIRED:'等待对账事实',TREND_UP:'上涨趋势',TREND_DOWN:'下跌趋势',RANGE:'震荡',UNKNOWN:'未知',UP:'向上',DOWN:'向下',MIXED:'结构交错',BREAK_PENDING:'破位待确认',BREAK_CONFIRMED:'破位已确认',STRUCTURE_ENVELOPE:'近期结构包络',STRUCTURE_UPDATED:'结构已更新',REENTERED:'返回区间',BREAK_FAILED:'破位未成立',WAIT:'等待机会',HOLD:'持有',HOLD_NO_ADD:'持有，暂停加仓',WAIT_CONFIRMATION:'等待破位确认',RECORD_ONLY:'日终记录',EXIT_REQUIRED:'需要退出',EXIT_OBLIGATION:'处理清仓义务',REDUCE_OBLIGATION:'保护已有仓位',MANAGE_PENDING:'管理未决动作',CHECK_ENTRY_ELIGIBILITY:'首仓资格已通过',CHECK_ADD_ELIGIBILITY:'加仓资格已通过',LONG:'多头',SHORT:'空头',FLAT:'空仓',OPEN:'首仓',ADD:'加仓',CLOSE:'退出',REJECT:'未通过',CONFIRMED_RANGE_NO_FIRST_ENTRY:'确认震荡，等待趋势机会',REQUIRED_FACTS_UNAVAILABLE:'必要事实不足',ORIGINAL_ENTRY_FACTS_NOT_READY:'首仓条件未齐',REGIME_DISALLOWS_ADD:'环境不允许加仓',WAIT_FRESH_POSITION:'等待新的合格位置',NO_DUPLICATE_ACTION:'已有未决动作，等待处理',BREAK_UP_PENDING:'向上破位，等待确认',BREAK_DOWN_PENDING:'向下破位，等待确认',DAY_END_NO_NEW_EXPOSURE:'日终只记录，禁止新增',RANGE_OPEN_GROSS_LOSS:'震荡持仓开盘毛浮盈亏损',RANGE_THREE_NONPOSITIVE_DAYS:'连续三日非正且开盘仍非正',EXISTING_FULL_EXIT:'既有全清义务继续',EXISTING_REDUCTION:'既有减仓义务继续',ORIGINAL_ENTRY_FACTS_READY:'原首仓事实齐全',FRESH_POSITION_AND_ORIGINAL_ADD_FACTS_READY:'新位置与加仓条件齐全'}
function label(v:any){return labels[v]??v??'未知'}
function money(v:any){return v==null?'未知':Number(v).toFixed(2)}
function time(v:string){return new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}
const plot=computed(()=>{const rows:Row[]=detail.value?.chart??[];const prices=rows.flatMap(r=>[r.close,r.lower,r.upper]).filter(x=>x!=null).map(Number);const lo=Math.min(...prices),hi=Math.max(...prices);const point=(r:Row,i:number,k:string)=>`${15+i*970/Math.max(1,rows.length-1)},${215-(Number(r[k])-lo)*190/Math.max(1,hi-lo)}`;return {rows,lo,hi,paths:['close','lower','upper'].map(k=>rows.map((r,i)=>r[k]==null?'':`${i===0||rows[i-1][k]==null?'M':'L'}${point(r,i,k)}`).join(' '))}})
</script>
<template>
  <div>
  <MarketNavigation active-tab="subing-decision" @market="home('market')" @messages="home('messages')" @simulation="home('simulation')" />
  <main class="decision-page">
    <div class="heading"><div><h1>苏冰决策 · 焦煤</h1><p>历史回放 · 研究候选 · 北京时间 · 非持续模型</p></div><label>历史窗口 <select v-model="run" aria-label="历史窗口" @change="select"><option v-for="r in runs" :key="r.id" :value="r.id">{{r.contract}} · {{r.since}} 至 {{r.through}}</option></select></label></div>
    <p v-if="error" role="alert">{{error}} <button @click="!run?loadRuns():overview?seek():select()">重试</button></p><p v-if="loading" role="status">正在读取回放…</p>
    <template v-if="overview">
      <section class="toolbar"><button :disabled="loading||index===0" @click="move(-1)">上一分钟</button><input v-model.number="index" type="range" min="0" :max="overview.times.length-1" aria-label="回放时刻" @input="offset=0;seek()"><button :disabled="loading||index===overview.times.length-1" @click="move(1)">下一分钟</button><strong>{{detail?time(detail.decision.at):'读取所选时刻…'}}</strong></section>
      <template v-if="d">
        <div class="grid"><section><h2>当前环境与主需求</h2><h3>{{label(d.demand)}}</h3><p>{{label(d.reason)}}</p><p>观察阶段：{{label(d.phase)}}</p><p v-if="d.opening_review">开盘复核毛浮盈：{{money(d.opening_review.gross_remaining)}}元 · {{label(d.opening_review.reason)}}；价格事实时刻 {{time(d.opening_review.price_at)}}</p><p>触发依据：{{d.trigger_reasons?.map(label).join('、')||'无新增退出触发'}}</p><dl><dt>日线准入方向</dt><dd>{{label(d.daily_direction)}} · {{d.daily_at?time(d.daily_at):'预热不足'}}</dd><dt>30m v2环境</dt><dd>{{label(d.regime)}}</dd><dt>近期结构</dt><dd>{{label(d.structure?.structure_direction)}} · {{label(d.structure?.phase)}} · 确认计数 {{d.structure?.count??0}}/4（含突破根）</dd><dt>边界</dt><dd>{{money(d.structure?.lower)}} — {{money(d.structure?.upper)}}</dd></dl><p v-if="d.conflict" class="notice">v2与结构方向存在分歧。以v2分类为基础，破位待确认另行限制新增。</p><p>下一步：{{label(d.next_wait)}}</p><p>支持依据：{{d.supporting_reasons?.map(label).join('、')||'未知'}}；条件缺口：{{d.condition_gaps?.map(label).join('、')||'无已知缺失'}}</p><p>60m观察：{{label(d.structure?.hourly?.direction)}} · {{d.structure?.hourly?.at?time(d.structure.hourly.at):'预热不足'}}；不参与交易许可。</p></section>
        <section><h2>条件检查</h2><dl><dt>环境允许新增</dt><dd>{{d.conditions.environment_allows_new?'通过':'等待'}}</dd><dt>资金及风险准入</dt><dd>{{d.conditions.risk_allows_new?'通过':'不通过'}}</dd><dt>EMA同侧</dt><dd>{{d.conditions.frame?.above_ema===true?'价格在EMA上方':d.conditions.frame?.below_ema===true?'价格在EMA下方':'未确认'}}</dd><dt>30m角度</dt><dd>{{money(d.conditions.frame?.minute_angle)}}</dd><dt>原始拒绝原因</dt><dd>{{d.blocking_reasons?.map(label).join('、')||'无'}}</dd><dt>当时放量</dt><dd>{{d.conditions.frame?.volume_effective===true?'有效':d.conditions.frame?.volume_effective===false?'不满足':'未知'}}</dd><dt>近轴交叉窗口</dt><dd v-for="side in ['LONG','SHORT']" :key="side">{{label(side)}}：{{d.conditions.entry_windows[side]?.source_end?`${time(d.conditions.entry_windows[side].source_end)} · 已过${d.conditions.entry_windows[side].age}根`:'等待新交叉'}}</dd></dl><p>条件按当时完成行情检查；机会通过后仍须严格后续模型成交。</p></section></div>
        <section><h2>30m价格与当时已知结构</h2><svg viewBox="0 0 1000 240" role="img" aria-label="30分钟价格与结构边界"><path v-for="(path,i) in plot.paths" :key="i" :d="path" fill="none" :stroke="['#d7ae62','#589ce7','#589ce7'][i]" stroke-width="2" :stroke-dasharray="i?'5 4':undefined"/></svg><p>{{plot.rows.length?time(plot.rows[0].at):''}} — {{plot.rows.length?time(plot.rows[plot.rows.length-1].at):''}} · 金色：收盘；蓝色：当时已知上下沿（{{money(plot.lo)}}～{{money(plot.hi)}}）</p></section>
        <section><h2>模型持仓与保护</h2><p>{{label(d.position.side??'FLAT')}} · {{d.position.quantity}}手 · 当前剩余仓位毛浮盈 {{money(d.gross_remaining)}}元</p><p>初始止损 {{money(d.position.initial_stop)}} · 1R目标 {{money(d.position.profit_target)}}</p><table><thead><tr><th>层</th><th>方向</th><th>成本</th></tr></thead><tbody><tr v-for="l in d.position.layers" :key="l.layer_id"><td>{{label(l.kind)}} · {{l.layer_id}}</td><td>{{label(l.side)}}</td><td>{{money(l.price)}}</td></tr></tbody></table><p>未决动作：{{d.position.pending?`${label(d.position.pending.kind)} · 等待后续执行`:'无'}}；清仓义务：{{d.position.clear_reasons.map(label).join('、')||'无'}}</p><p>本时刻动作：{{d.actions.map((a:Row)=>label(a.kind)).join('、')||'无新增动作'}}</p></section>
        <section><h2>截至当前的模型成交</h2><table><thead><tr><th>成交时间</th><th>动作</th><th>价格</th><th>原因</th></tr></thead><tbody><tr v-for="(f,i) in detail?.fills" :key="i"><td>{{time(f.fill_at)}}</td><td>{{label(f.action)}}</td><td>{{money(f.price)}}</td><td>{{f.reasons.map(label).join('、')}}</td></tr></tbody></table><p v-if="!detail?.fills.length">截至当前没有模型成交。</p></section>
        <section><h2>决策历史</h2><table><thead><tr><th>时刻</th><th>环境</th><th>需求</th><th>依据</th></tr></thead><tbody><tr v-for="r in history" :key="r.at"><td>{{time(r.at)}}</td><td>{{label(r.regime)}}</td><td>{{label(r.demand)}}</td><td>{{label(r.reason)}}</td></tr></tbody></table><button :disabled="offset===0" @click="offset=Math.max(0,offset-30);seek()">较新</button><button :disabled="offset+30>index" @click="offset+=30;seek()">较早</button></section>
      </template>
      <details><summary>完整窗口绩效（含游标之后结果，独立账户，不是当时决策依据）</summary><p>各窗口独立10万元；理论后续开盘撮合、1tick滑点和实际费用；已见开发样本，非OOS。</p><table><thead><tr><th>版本</th><th>净损益</th><th>费用</th><th>成交数</th></tr></thead><tbody><tr v-for="(v,k) in overview.summary" :key="k"><template v-if="v.summary"><td>{{{baseline:'原基线',previous_candidate:'既有v2候选',candidate:'统一候选'}[k as string]??k}}</td><td>{{money(v.summary.net_pnl)}}</td><td>{{money(v.summary.fees)}}</td><td>{{v.fills}}</td></template></tr></tbody></table></details>
    </template>
  </main>
  </div>
</template>
<style scoped>
.decision-page{padding:24px;max-width:1500px;margin:auto;color:var(--gy-text-primary);font-size:14px}.heading,.toolbar{display:flex;align-items:center;gap:18px;justify-content:space-between}.heading p,section>p,details p{color:var(--gy-text-secondary)}h1{font-size:24px;margin:0}h2{font-size:16px;margin:0 0 16px}h3{font-size:22px;color:#d7ae62}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}section,details{background:var(--gy-bg-surface,var(--gy-bg-header));border:1px solid var(--gy-border-subtle);border-radius:8px;padding:20px;margin:16px 0}select,button{background:var(--gy-bg-header);color:var(--gy-text-primary);border:1px solid var(--gy-border-subtle);border-radius:5px;padding:8px}button{cursor:pointer}button:disabled{opacity:.4}input[type=range]{flex:1}dl{display:grid;grid-template-columns:150px 1fr;gap:12px}dd{margin:0}svg{width:100%;height:260px;background:var(--gy-bg-header)}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:10px;border-bottom:1px solid var(--gy-border-subtle)}.notice,[role=alert]{color:#d7ae62}summary{cursor:pointer}
</style>
